// Declared here so the completion rules below can classify exactly typed
// element symbols before the formula reader is defined.
inline const char* const* elementSymbols(size_t* count);
inline bool isElementSymbol(const std::string& text);
inline std::string key(const std::string& value){if(compounddata::find(value))return compounddata::key(value);std::string result;for(unsigned char c:value){if(c=='-')continue;if(c>=128||c<=32)return std::string();result+=char(c>='A'&&c<='Z'?c+32:c);}return result;}
// Case-insensitive element collision test, used when user-defined abbreviations
// must not shadow an element symbol (nicknames.hpp) or a custom alias is added.
// Auto-completion itself no longer uses this: the exact case decides there.
inline bool protectedKey(const std::string& value){
    if(value.empty())return true;
    size_t count=0;
    const auto symbols=elementSymbols(&count);
    for(size_t i=0;i<count;++i)if(key(symbols[i])==value)return true;
    return false;
}
// ---- user state -----------------------------------------------------------
struct State {
    std::set<std::string> disabled;                   // lower-case dictionary keys
    std::map<std::string,std::string> custom;         // key -> canonical spelling
    unsigned revision=1;
};
inline void loadState(State& state){
    state.disabled.clear();state.custom.clear();
    std::string raw=readKey(L"Disabled");
    for(size_t at=0;at<raw.size();){size_t end=raw.find('|',at);if(end==std::string::npos)end=raw.size();if(end>at)state.disabled.insert(raw.substr(at,end-at));at=end+1;}
    raw=readKey(L"Custom");
    for(size_t at=0;at<raw.size();){size_t end=raw.find('|',at);if(end==std::string::npos)end=raw.size();std::string item=raw.substr(at,end-at);size_t eq=item.find('=');if(eq!=std::string::npos&&eq>0&&eq+1<item.size())state.custom[item.substr(0,eq)]=item.substr(eq+1);at=end+1;}
}
inline State& state(){static State value=[](){State loaded;loadState(loaded);return loaded;}();return value;}
inline bool persist(State& draft){
    std::string disabled;for(const auto& name:draft.disabled)disabled+=name+"|";
    std::string custom;for(const auto& entry:draft.custom)custom+=entry.first+"="+entry.second+"|";
    if(!writeKey(L"Disabled",disabled)||!writeKey(L"Custom",custom))return false;
    unsigned revision=state().revision+1;loadState(state());state().revision=revision;
    return true;
}
// ---- dictionary -----------------------------------------------------------
inline const std::map<std::string,std::string>& index(){
    static std::map<std::string,std::string> values;static unsigned built=0;
    if(built!=state().revision){
        values.clear();
        for(const auto& entry:nickdata::nicknames){
            auto k=key(entry.name);if(k.empty())continue;
            // Element-named entries are NOT skipped: the exact spelling still wins
            // in normalize()/chemicalToken(), while lower-case input (cn, li, pr)
            // is an abbreviation that must reach the dictionary (CN, Li, Pr).
            auto it=values.find(k);
            if(it==values.end())values[k]=entry.name;
            else if(it->second!=entry.name)it->second.clear();
        }
        // Explicit, reviewed typography choices: aliases in the historical catalog
        // are not necessarily equivalent, so ambiguous entries above stay unset.
        // The compact spellings are the reviewed standard for the common alkyl
        // prefixes (tbu -> tBu); i-Am/n-Am/s-Am/t-Am stay unresolved by policy.
        for(const char* canonical:{"tBu","sBu","iBu","nBu","iPr","nPr"})if(nickdata::find(canonical))values[key(canonical)]=canonical;
        if(nickdata::find("tBu")){values["tertbu"]="tBu";values["tertbutyl"]="tBu";}
        if(nickdata::find("sBu")){values["secbu"]="sBu";values["secbutyl"]="sBu";}
        for(const auto& alias:compounddata::index())if(alias.second.entry&&!values.count(alias.first))
            values[alias.first]=alias.second.spelling;
        for(const auto& entry:state().custom){values[entry.first]=entry.second;values[key(entry.second)]=entry.second;}
        customgroups::load();for(const auto& entry:customgroups::entries())values[key(entry.name)]=entry.name;
        for(const auto& entry:state().disabled)values.erase(entry);
        built=state().revision;
    }
    return values;
}
// ---- formula spelling -----------------------------------------------------
inline const char* const* elementSymbols(size_t* count){
    static const char* const symbols[]={"H","He","Li","Be","B","C","N","O","F","Ne","Na","Mg","Al","Si","P","S","Cl","Ar","K","Ca","Sc","Ti","V","Cr","Mn","Fe","Co","Ni","Cu","Zn","Ga","Ge","As","Se","Br","Kr","Rb","Sr","Y","Zr","Nb","Mo","Tc","Ru","Rh","Pd","Ag","Cd","In","Sn","Sb","Te","I","Xe","Cs","Ba","La","Ce","Pr","Nd","Pm","Sm","Eu","Gd","Tb","Dy","Ho","Er","Tm","Yb","Lu","Hf","Ta","W","Re","Os","Ir","Pt","Au","Hg","Tl","Pb","Bi","Po","At","Rn","Fr","Ra","Ac","Th","Pa","U","Np","Pu","Am","Cm","Bk","Cf","Es","Fm","Md","No","Lr","Rf","Db","Sg","Bh","Hs","Mt","Ds","Rg","Cn","Nh","Fl","Mc","Lv","Ts","Og"};
    static const size_t size=sizeof(symbols)/sizeof(symbols[0]);
    if(count)*count=size;
    return symbols;
}
inline bool isElementSymbol(const std::string& text){
    size_t count=0;const char* const* symbols=elementSymbols(&count);
    for(size_t i=0;i<count;++i)if(text==symbols[i])return true;
    return false;
}
struct FormulaReading {bool ok=false,hasGroup=false,hasPrefix=false;int tokens=0;std::string text;};
// Reviewed abbreviations that can safely be recognized inside a formula.
inline std::string compositeGroup(const std::string& text,size_t at,size_t* consumed){
    static const char* const groups[]={
        "Ph","Me","Et","Bn","Bz","Ac","Boc","Cbz","Fmoc","Piv","Ts","Tf","Ns","Mes","Tol","Naph",
        "t-Bu","s-Bu","n-Bu","i-Bu","i-Pr","n-Pr","TMS","TBS","TIPS","Bpin","Cp","Cp*",
        "ppy","bpy","phen","acac","cod","dppe","dppp","dppf"
    };
    std::string best;
    *consumed=0;
    for(const auto* group:groups){
        auto compact=std::string(group);
        compact.erase(std::remove(compact.begin(),compact.end(),'-'),compact.end());
        for(const std::string& form:{std::string(group),compact}){
            const size_t n=form.size();
            if(n<=*consumed||at+n>text.size())continue;
            const auto token=text.substr(at,n);
            auto lower=form;
            for(auto& c:lower)if(c>='A'&&c<='Z')c=char(c+32);
            // Explicit uppercase element sequences such as PH3 keep their case.
            if(token!=form&&token!=lower)continue;
            best=state().disabled.count(key(group))?token:group;*consumed=n;
        }
    }
    return best;
}
// twoLetter reads "Co"/"Cu" as one element; the other reading takes every
// letter as its own symbol (CO2, CS2, NH4+).
inline bool readFormula(const std::string& text,bool twoLetter,FormulaReading* reading,bool groups=false){
    FormulaReading result;
    size_t at=0,length=text.size();
    if(groups)for(const char* prefix:{"fac-","mer-","cis-","trans-","syn-","anti-","endo-","exo-","meso-","ortho-","meta-","para-","o-","m-","p-"}){
        const size_t n=std::strlen(prefix);
        if(text.compare(0,n,prefix)==0){result.text=prefix;result.hasPrefix=true;at=n;break;}
    }
    while(at<length){
        char c=text[at];
        if(c>='0'&&c<='9'){
            size_t stop=at;while(stop<length&&text[stop]>='0'&&text[stop]<='9')++stop;
            result.text+=text.substr(at,stop-at);at=stop;continue;
        }
        if(c=='('||c==')'||c=='['||c==']'||c=='+'||c=='-'||c=='*'||c=='.'){result.text+=c;++at;continue;}
        if(!((c>='A'&&c<='Z')||(c>='a'&&c<='z')))return false;
        if(groups){
            size_t consumed=0;
            const auto group=compositeGroup(text,at,&consumed);
            if(!group.empty()){
                result.text+=group;result.hasGroup=true;++result.tokens;at+=consumed;continue;
            }
        }
        std::string symbol(1,char(c>='a'?c-32:c));
        if(twoLetter&&at+1<length&&text[at+1]>='a'&&text[at+1]<='z'&&isElementSymbol(symbol+text[at+1])){
            result.text+=symbol+text[at+1];++result.tokens;at+=2;continue;
        }
        if(!isElementSymbol(symbol))return false;
        result.text+=symbol;++result.tokens;++at;
    }
    result.ok=true;if(reading)*reading=result;return true;
}
